def sort_versions(versions):
    def parse(v):
        # ignore build metadata
        v = v.split('+', 1)[0]
        if '-' in v:
            main, pre = v.split('-', 1)
            pre_ids = pre.split('.')
            pre_tuple = []
            for pid in pre_ids:
                if pid.isdigit():
                    pre_tuple.append((0, int(pid)))
                else:
                    pre_tuple.append((1, pid))
            pre_tuple = tuple(pre_tuple)
            prerelease_flag = 0  # prerelease comes before release
        else:
            main = v
            pre_tuple = ()
            prerelease_flag = 1  # release comes after prerelease
        major, minor, patch = map(int, main.split('.'))
        return (major, minor, patch, prerelease_flag, pre_tuple)
    return sorted(versions, key=parse)
